package Leetcode;
public class Solutions {
    public static void main(String[] args) {
        String s = "\"\"";
        System.out.println(numSub(s));
    }

    // helper function
    // n = 1 - 1
    // n = 2 - 2 + 1
    // n = 3 - 3 + 2 + 1
    // n = 4 - 4 + 2 + 3 + 1
    // n = k - k*(k + 1)/2
    public static int helper(int n){
        if (n <= 1) {
            return n;
        }

        int result = n*(n+1)/2;

        if (result >= 200000000) {
            return 100000000 + 7; 
        }

        return result;
    }

    public static int numSub(String s){
        int n = 0, total = 0;

        int len = s.length();
        for (int i = 0; i < len; i++) {
            if (s.charAt(i) == '1') {
                n++;
            }
            if (s.charAt(i) != '1' || i >= len - 1) {
                total += helper(n);
                n = 0;
            }
        }

        return total;
    }
}
